head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf50200";
scwin.reg_button = null;
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — result

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "ul_30", attr: "__html", fn: function () { return ([String(dma_page.get("total")), String(dma_page.get("currentPage")), String(dma_page.get("pageCount"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("총 <strong id=\"totPage\">" + String(dma_page.get("total")) + "</strong>건 <span id=\"totPage1\">(" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + ")</span>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_result", fn: function(){ return (!(String(((dma_pageContext.get("result") ?? "")) == null ? '' : ((dma_pageContext.get("result") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const pageIndex = "" + dma_page.get("currentPage") + "";
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf50200.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(fee#feepayofcdocreqview vs fee#feepayofcdocreq) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":5
        ,"mmenu":2
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf50200' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.reg_button = $c.util.getComponent('reg_button');
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf50200.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dataTb_oncellclick
 * @description dataTb 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataTb_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["applRsltCd"] === 'Y') { scwin.PopUp_FeeOfcdocReport(r["payOfcdocReqSeq"]); return; } return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'dataTb.oncellclick' });
    }
};

/**
 * @method
 * @name ipt_payAmt_onkeyup
 * @description ipt_payAmt 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_payAmt_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.util.getComponent('txt_amtStr').setValue($c.num.formatNumberKor(String((((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar))))) == null ? '' : (((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar)))))).replace(/,/g, '')));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf50200.ipt_payAmt_onkeyup' }); }
};

/**
 * @method
 * @name btn_OfcdocReq_onclick
 * @description btn_OfcdocReq 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_OfcdocReq_onclick = async function(e){
    try {
        await scwin.ofcdocReq()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf50200.btn_OfcdocReq_onclick' }); }
};

/**
 * @method
 * @name btn_cancelForm_onclick
 * @description btn_cancelForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_cancelForm_onclick = function(e){
    try {
        scwin.cancel_form()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf50200.btn_cancelForm_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_search
 * @description search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/fee/fee.do?method=feePayOfcdocReqView",
        ref: "dma_searchReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goPage
 * @description go Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goPage = async function () {
    const sbmOptions = {
        id: "tx_fn_goPage",
        method: "post",
        action: "/fee/fee.do?method=feePayOfcdocReqView",
        ref: "dma_goPageReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_PopUp_FeeOfcdocReport
 * @description Pop Up Fee Ofcdoc Report 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_PopUp_FeeOfcdocReport = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_PopUp_FeeOfcdocReportReq") ? $c.util.getComponent("dma_PopUp_FeeOfcdocReportReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fn_OfcdocReq
 * @description Ofcdoc Req 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_OfcdocReq = async function () {
    const sbmOptions = {
        id: "tx_fn_OfcdocReq",
        method: "post",
        action: "/fee/fee.do?method=feePayOfcdocReq",
        ref: "dma_OfcdocReqReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name dataTb_fillAct
 * @description data Tb fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataTb_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'dataTb.fillAct' });
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.JLDINF50200 || { elements: [] });
    frm.action = "/fee/fee.do?method=feePayOfcdocReqView";
    frm.target = "_self";
    blockLoading();
    await scwin.tx_fn_search();
};

/**
 * @method
 * @name goPage
 * @description go Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goPage = async function () {
    const frm = (document.JLDINF50200 || { elements: [] });
    frm.action = "/fee/fee.do?method=feePayOfcdocReqView";
    blockLoading();
    await scwin.tx_fn_goPage();
};

/**
 * @method
 * @name PopUp_FeeOfcdocReport
 * @description Pop Up Fee Ofcdoc Report 처리
 * @param {*} pay_ofcdoc_req_seq pay_ofcdoc_req_seq
 * @returns {void}
 * @hidden N
 */
scwin.PopUp_FeeOfcdocReport = function (pay_ofcdoc_req_seq) {
    $.ajax({ type: "POST", async: false, url: "/fee/fee.do?method=ofcdocReportCommonAjax&pay_ofcdoc_req_seq=" + pay_ofcdoc_req_seq, data: {  }, success: async function(data) {
                const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                const form = (document.newReportForm || { elements: [] });
                for (key in result) {
                    if (form[camelize(key)]) {
                        form[camelize(key)].value = result[key];
                    }
                }
                await scwin.tx_PopUp_FeeOfcdocReport();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
};

/**
 * @method
 * @name PopUp_FeeOfcdocReport_old
 * @description Pop Up Fee Ofcdoc Report old 처리
 * @param {*} pay_ofcdoc_req_seq pay_ofcdoc_req_seq
 * @returns {void}
 * @hidden N
 */
scwin.PopUp_FeeOfcdocReport_old = function (pay_ofcdoc_req_seq) {
    const rexName = "JLDINF50200";
    const dataType = "XML";
    const dataLocation = "/fee/fee.do?method=ofcdocReportView&pay_ofcdoc_req_seq=" + pay_ofcdoc_req_seq;
    const dataXPath = "main/rpt1";
    fn_PrintPreView_DB(rexName, dataType, dataLocation, dataXPath);
};

/**
 * @method
 * @name ofcdocReq
 * @description ofcdoc Req 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ofcdocReq = async function () {
    const frm = (document.JLDINF50200 || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_payAmt').getValue()) === 0) {
        await $c.win.alert("선납금액(예정)을  입력하세요");
        $c.util.getComponent("ipt_payAmt").focus();
        return;
    }
    scwin.reg_button.setStyle("display", "none");
    frm.action = "/fee/fee.do?method=feePayOfcdocReq";
    frm.target = "_top";
    await scwin.tx_fn_OfcdocReq();
};

/**
 * @method
 * @name cancel_form
 * @description cancel form 처리
 * @returns {void}
 * @hidden N
 */
scwin.cancel_form = function () {
    (document.JLDINF50200 || { elements: [] }).reset();
    $c.util.getComponent('txt_amtStr').setLabel("");
};

/**
 * @method
 * @name krxpage_pagenavigator_74_onclick
 * @description krxpage_pagenavigator_74 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_74_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        await scwin.goPage();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldinf50200.krxpage_pagenavigator_74_onclick" });
    }
};
